<script setup lang="ts">
import {ref,computed,watch} from 'vue'
const props=defineProps<{open:boolean,value:string,dark:boolean}>(),emit=defineEmits<{close:[],select:[value:string]}>()
const year=ref(2026),month=ref(10),choice=ref(''),months=ref(false)
function iso(d:Date){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const today=()=>iso(new Date())
const days=computed(()=>{const first=new Date(year.value,month.value-1,1),offset=(first.getDay()+6)%7,count=new Date(year.value,month.value,0).getDate();return Array.from({length:Math.ceil((offset+count)/7)*7},(_,i)=>{const day=i-offset+1;return day<1||day>count?null:{day,date:iso(new Date(year.value,month.value-1,day))}})})
function shift(n:number){if(months.value){year.value+=n;return}const d=new Date(year.value,month.value-1+n,1);year.value=d.getFullYear();month.value=d.getMonth()+1}
function current(){choice.value=today();const d=new Date();year.value=d.getFullYear();month.value=d.getMonth()+1;months.value=false}
function confirm(){emit('select',choice.value);emit('close')}
watch(()=>props.open,v=>{if(v){const parts=props.value.split('-').map(Number);year.value=parts[0];month.value=parts[1];choice.value=props.value;months.value=false}})
</script>
<template><view v-if="open" class="date-mask" :class="{dark}" @click="emit('close')"><view class="date-sheet" @click.stop><view class="date-handle"/><view class="date-heading"><text>选择日期</text><view @click="emit('close')">×</view></view><view class="date-month"><view @click="shift(-1)">‹</view><text @click="months=!months">{{year}}年{{months?'':month+'月'}} <text class="date-caret">⌄</text></text><view @click="shift(1)">›</view></view><view v-if="months" class="month-grid"><view v-for="n in 12" :key="n" :class="{selected:n===month}" @click="month=n;months=false">{{n}}月</view></view><template v-else><view class="weekday-grid"><text v-for="d in ['一','二','三','四','五','六','日']" :key="d">{{d}}</text></view><view class="date-grid"><view v-for="(d,i) in days" :key="i" :class="{selected:d?.date===choice,today:d?.date===today(),weekend:i%7>=5}" @click="d&&(choice=d.date)"><text v-if="d">{{d.day}}</text><view v-if="d?.date===today()" class="date-today-dot"/></view></view></template><view class="date-selected"><text>已选 {{choice.split('-').join(' / ')}}</text><text @click="current">回到今天</text></view><button class="date-confirm" @click="confirm">查看这一天</button></view></view></template>
<style scoped lang="scss">
.date-mask{--p:#fff;--ink:#18304f;--muted:#94a1b5;--soft:#f2f7fc;position:fixed;inset:0;background:#07182b70;z-index:50;display:flex;align-items:flex-end;backdrop-filter:blur(7px)}.dark{--p:#1b2b44;--ink:#edf3ff;--muted:#98abc8;--soft:#243751}.date-sheet{width:100%;max-width:1000rpx;margin:auto auto 0;background:var(--p);color:var(--ink);border-radius:40rpx 40rpx 0 0;padding:14rpx 35rpx calc(25rpx + env(safe-area-inset-bottom))}.date-handle{width:64rpx;height:7rpx;background:#a8b7ca44;border-radius:10rpx;margin:0 auto 27rpx}.date-heading{display:flex;justify-content:space-between;align-items:center;font-size:32rpx;font-weight:650}.date-heading>view{font-size:34rpx;color:var(--muted);font-weight:400;width:50rpx;text-align:right}.date-month{display:flex;justify-content:space-between;align-items:center;margin:23rpx 0;color:var(--ink);font-size:30rpx;font-weight:600}.date-month>view{width:65rpx;height:65rpx;border-radius:18rpx;background:var(--soft);text-align:center;line-height:58rpx;font-size:44rpx;font-weight:400;color:#6599d8}.date-caret{font-size:23rpx;color:var(--muted);margin-left:10rpx}.weekday-grid,.date-grid{display:grid;grid-template-columns:repeat(7,1fr);text-align:center}.weekday-grid{font-size:22rpx;color:var(--muted);margin:25rpx 0 15rpx}.date-grid>view{position:relative;display:flex;align-items:center;justify-content:center;height:76rpx;border-radius:20rpx;margin:4rpx;font-size:27rpx}.date-grid .weekend{color:#8d9fb8}.date-grid .today{color:#287bf5;font-weight:650}.date-grid .selected{color:#fff;background:linear-gradient(140deg,#4c9bff,#2477ef);box-shadow:0 6rpx 18rpx #287bf530;font-weight:650}.date-today-dot{position:absolute;bottom:9rpx;width:5rpx;height:5rpx;border-radius:50%;background:currentColor}.date-selected{display:flex;justify-content:space-between;align-items:center;background:var(--soft);border-radius:18rpx;padding:18rpx 20rpx;margin-top:23rpx;font-size:22rpx;color:var(--muted)}.date-selected>text+text{color:#4188e4}.date-confirm{background:#287bf5;color:#fff;height:86rpx;line-height:86rpx;font-size:26rpx;border-radius:21rpx;margin-top:23rpx}.month-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:17rpx;padding:15rpx 0}.month-grid>view{text-align:center;background:var(--soft);padding:22rpx 0;border-radius:18rpx;font-size:26rpx}.month-grid .selected{color:#287bf5;background:#e7f2ff}
</style>
